SELECT id, create_by AS createBy, create_time AS createTime, update_by AS updateBy, update_time AS updateTime, deleted, version, user_id AS userId, owner_user_id AS ownerUserId, trigger_user_id AS triggerUserId, operator_user_id AS operatorUserId, trigger_type AS triggerType, visibility, task_type AS taskType, task_name AS taskName, plan_id AS planId, unit_id AS unitId, related_job_id AS relatedJobId, business_type AS businessType, business_id AS businessId, idempotency_key AS idempotencyKey, status, execution_mode AS executionMode, scheduled_time AS scheduledTime, priority, total_count AS totalCount, success_count AS successCount, failed_count AS failedCount, progress_percent AS progressPercent, retry_count AS retryCount, max_retry_count AS maxRetryCount, error_message AS errorMessage, started_time AS startedTime, finished_time AS finishedTime, cancelled_time AS cancelledTime FROM learning_ai_async_task WHERE deleted = 0
AND owner_user_id = #{ownerUserId}
AND status = #{status}
ORDER BY create_time DESC
